<script>(()=>{const tabs=document.getElementById('accountantProjectTabs'),sections=Array.from(document.querySelectorAll('.main>section'));if(!tabs||sections.length<5)return;const groups={overview:[sections[0],sections[1]],billing:[sections[2]],costs:[sections[3],sections[4]]};const show=name=>{Object.values(groups).flat().forEach(section=>section.hidden=true);(groups[name]||groups.overview).forEach(section=>section.hidden=false);tabs.querySelectorAll('button').forEach(button=>{button.classList.toggle('btn-primary',button.dataset.projectView===name);button.classList.toggle('btn-ghost',button.dataset.projectView!==name)});history.replaceState(null,'','#'+name)};tabs.addEventListener('click',event=>{const button=event.target.closest('[data-project-view]');if(button)show(button.dataset.projectView)});show(location.hash.slice(1)||'overview')})();</script>
